import sys

def nthCharacter(S, R, N):
    current = S
    for _ in range(R):
        next_s = []
        for char in current:
            if char == '0':
                next_s.append('0')
                next_s.append('1')
            else:
                next_s.append('1')
                next_s.append('0')
        current = "".join(next_s)

    return current[N]

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        S = next(iterator)
        R = int(next(iterator))
        N = int(next(iterator))

        result = nthCharacter(S, R, N)
        print(result)
    except StopIteration:
        pass

if __name__ == "__main__":
    main()
